import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({ base: './', plugins: [vue()] })

import { createRouter, createWebHashHistory } from 'vue-router'
import DashboardView from '../views/DashboardView.vue'
import UserListView from '../views/UserListView.vue'

export default createRouter({
  history: createWebHashHistory(),
  routes: [
    { path: '/', component: DashboardView },
    { path: '/users', component: UserListView }
  ]
})

:root { font-family: Inter, system-ui, sans-serif; color: #24324a; background: #f3f6fb; }
* { box-sizing: border-box; }
body { margin: 0; }
.layout { min-height: 100vh; }
.el-aside { background: #fff; border-right: 1px solid #e6eaf0; }
.logo { height: 64px; display: flex; align-items: center; padding: 0 22px; font-weight: 800; color: #3157d5; }
.el-menu { border-right: 0; }
.el-header { display: flex; align-items: center; justify-content: space-between; background: #fff; border-bottom: 1px solid #e6eaf0; }
.el-main { padding: 28px; }
.heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px; }
h1 { margin: 0 0 6px; font-size: 24px; }
p { margin: 0; color: #8791a3; }
.metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-bottom: 18px; }
.metrics .el-card__body { display: grid; gap: 10px; }
.metrics strong { font-size: 28px; }
.metrics small { color: #42a66a; }
@media (max-width: 800px) { .el-aside { width: 72px !important; } .logo { font-size: 0; } .logo::after { content: '启明'; font-size: 15px; } .metrics { grid-template-columns: 1fr; } }
